export const MERCHANT_CONSOLE_SELECTION_SCHEMA = 'stellar-forge.merchant-console-selection.v1';
export const MERCHANT_CONSOLE_STARTUP_SCHEMA = 'stellar-forge.merchant-console-startup.v1';
